style.css:
@-moz-document domain("espn.com"), domain("espn.co.uk"), domain("espn.com.au"), domain("espn.in") {
:root { color-scheme: dark !important; }

  /* ---- Base surfaces ---- */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  #global-viewport, #main-container, #content, .main-content, .page-container,
  .layout, [class*="layout-"], .contentFeed, .one-feed-wrapper, .container,
  .col-a, .col-b, .col-c, .col-one, .col-two, .col-three, .col-main {
    background-color: transparent !important; }
  .main-content, #global-scoreboard, .scoreboard-content { background-color: #14181d !important; }

  /* ---- Soften all default light borders ---- */
  * { border-color: #262c33 !important; }

  /* ---- Header / global nav ---- */
  #global-header, #custom-nav, .Nav, .Site--nav, header[role="banner"] { background-color: #0d1117 !important; }
  #global-nav, .Nav__Primary, .Nav__Secondary, #global-nav-secondary,
  .global-nav-container, .navigation { background-color: #0d1117 !important; }
  #global-header { border-bottom: 2px solid #c8102e !important; } /* ESPN red accent */
  .Nav__Primary__Menu, .Nav__Dropdown, .Nav__Dropdown__Menu, .dropdown-menu,
  .Flyout, .Flyout__Inner { background-color: #1c2128 !important; }
  .Nav a, .nav__link, #global-nav a, .Nav__Primary__Menu__Link,
  .Nav__Secondary__Menu__Link, .global-nav a { color: #e6edf3 !important; }
  .Nav a:hover, #global-nav a:hover, .Nav__Primary__Menu__Link:hover { color: #ffffff !important; }
  .nav-menu, .menu-flyout, .QuickMenu, .HeaderUserMenu, .HeaderUserMenu__Menu { background-color: #1c2128 !important; }

  /* ---- Scoreboard strip / score chips ---- */
  #global-scoreboard, .HeaderScoreboard, .HeaderScoreboard__Wrapper,
  .scores-carousel, .scoreboards, .scoreboard { background-color: transparent !important; }
  .cscore, .cscore_item, .cscore_link, .scoreboard, .gameStrip, .game-strip,
  .Scoreboard, .ScoreCell, .ScoreboardScoreCell {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .cscore_name, .cscore_score, .ScoreCell__Score, .ScoreCell__TeamName,
  .gameStrip__competitors, .ScoreboardScoreCell__Item,
  .scoreEvent__athlete, .scoreEvent__score, .scoreEvent__position,
  .scoreEvent__description, .scoreEvent__competitors, .cscore_rank,
  .cscore_aggregate, .scoreCell__Score, .gameStrip__team-name { color: #e6edf3 !important; }
  .cscore_date-time, .cscore_network, .cscore_info, .cscore_info-overview,
  .cscore_notes, .cscore_status, .cscore_odds, .scoreEvent__status,
  .ScoreCell__Time, .Schedule__Time, .scoreEvent__event, .scoreEvent__title { color: #8b949e !important; }
  .media-duration, .video-length, .timestamp--overlay { color: #ffffff !important; }

  /* ---- Score-section labels / headers (default light bg) ---- */
  #pane-main, .scoreLabel_content, .scoreLabel, #favfeed-footer {
    background-color: #14181d !important; }
  .scoreLabel_title, .ContentList__Header, .Card__Header,
  .section-header, .mod-header, h2[class*="Label"] {
    background-color: transparent !important; color: #e6edf3 !important; }
  #favfeed-footer a { color: #8ab4d8 !important; }

  /* ---- Betting widgets (default very-light bg) ---- */
  .betting, [class*="betting"], .bettingLabel, .bettingPrimary, .bettingSecondary,
  .bettingTeamSeparator, .Betting, .ProviderLogo, .pick-center-data {
    background-color: #181d23 !important; }
  .betting *, [class*="betting"] * { color: #c4cdd6 !important; }

  /* ---- DTC / ESPN+ upsell tiles (default white) ---- */
  .dtc-upsell, [class*="dtc-upsell"], .Espnplus, .WatchTile, .WatchTile__Content,
  .upsell, .premiumUpsell { background-color: #1a1f26 !important; border-color: #2d333b !important; }
  .dtc-upsell__cta__btn, .WatchTile__Button {
    background-color: #c8102e !important; color: #ffffff !important; border-color: #c8102e !important; }

  /* ---- Content cards / feed items ---- */
  .contentItem, .contentItem--collection, .contentItem--featured,
  .contentItem--game-strip, .contentItem--headlineStack, article.contentItem,
  .contentCollection, .contentCollection--hero, .headlineStack, .headlineStack--top-headlines,
  .sub-module, .sub-module.editorial, article.sub-module, .module, .module.sideLogin,
  .sideLogin, .Card, .card, .scoreCollection, .scoreEvent, .scoreEvent__content,
  .MiniCard, .miniCard, .now-feed-item, .news-feed-item, .QuickLinks,
  .contentItem__padding--border, .mod-container, .mod-content {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .contentItem--featured, .contentCollection--hero { background-color: #1a1f26 !important; }
  .contentItem:hover, .scoreEvent__content:hover, .cscore_link:hover,
  .news-feed-item:hover { background-color: #21262d !important; }

  /* ---- Typography ---- */
  h1, h2, h3, h4, h5, h6, .contentItem__subhead, .Card__Header__Title,
  .QuickLinks__Item__Title, .headline, .Story__Headline { color: #e6edf3 !important; }
  p, li, span, dd, dt, td, th, label, figcaption, time, small, b, strong, em,
  .contentItem__subhead, .news-feed-item p, .photoCaption, .sub-module .content p,
  .cscore_truncate { color: #c4cdd6 !important; }

  /* ---- Links: ESPN headline blue is too dark on dark → readable blue ---- */
  a, a span { color: #5fb0e6 !important; }
  a:hover { color: #9bd4ff !important; }
  /* headline links inside cards: bright, high-contrast */
  .contentItem__title, .contentItem__title--story, .contentItem__title--hero,
  .contentItem__title a, .headlineStack__list > li > a,
  .contentItem--headlineStack__list > li > a, .news-feed-item h1 a,
  .QuickLinks__Item__Title a, .AnchorLink {
    color: #e6edf3 !important; }
  .contentItem__title a:hover, .headlineStack__list > li > a:hover,
  .AnchorLink:hover { color: #5fb0e6 !important; }

  /* ---- Story / article body ---- */
  .article, #article-feed .article, .article-body, .Story, .Story__Body,
  .story-container, .article-header, .ContentList, .Article {
    background-color: transparent !important; color: #c4cdd6 !important; }
  .article-body p, .Story__Body p, .article-body li, .article p { color: #c4cdd6 !important; }
  .article-meta, .byline, .timestamp, .author, .article-timestamp, .Byline { color: #8b949e !important; }
  blockquote, .article-body aside.inline, aside.inline {
    background-color: #1a1f26 !important; border-left: 3px solid #2d333b !important; color: #c4cdd6 !important; }
  figure, .article-figure { background-color: transparent !important; }
  .container-wrapper, .article-feed, .article-feed__container,
  .inline-content, .Story__feed { background-color: transparent !important; }
  /* reaction / share / icon buttons: dark glyph on dark → readable */
  .icon-button, .reactions-button, .reactions-button svg, .icon-button svg,
  .share-buttons button, .article-social .btn-social {
    color: #c4cdd6 !important; fill: #c4cdd6 !important; }
  .icon-button:hover, .reactions-button:hover { color: #e6edf3 !important; fill: #e6edf3 !important; }
  /* video play-button overlay: keep dark, not a bright leak */
  .video-play-button, .Poster__Button, .media-wrapper__playbtn,
  .play-button, .VideoControls__PlayButton {
    background-color: rgba(20,24,29,0.7) !important; }

  /* ---- Tables (stats / standings) ---- */
  .Table, .Table2, table, .tablehead, .mpTable > table, .Table__TBODY,
  .Table2__table { background-color: transparent !important; }
  .Table__THEAD, .Table2__thead, thead, .Table__TH, .Table2__th, th,
  .tablehead tr.colhead, .Table__sub-header {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .Table__TR, .Table2__tr, tr, td, .Table__TD, .Table2__td, .tablehead td {
    border-color: #2d333b !important; color: #c4cdd6 !important; }
  .Table__TR--sm, tr:nth-child(even), .Table__even { background-color: #181d23 !important; }
  .Table__TR:hover, tr:hover { background-color: #21262d !important; }

  /* ---- Forms / inputs / search ---- */
  input, textarea, select, .search-box, .Search__Input {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  input::placeholder { color: #8b949e !important; }

  /* ---- Buttons ---- */
  .button, .btn, .Button, .button-alt, .button-filter, .btn-social,
  .pick-center-data .btn, .Nav__SignUp {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .button:hover, .btn:hover, .Button:hover { background-color: #2d333b !important; }
  .button--primary, .Button--primary, .btn--alt, .Nav__SignUp--filled,
  .ContentList__Button {
    background-color: #c8102e !important; border-color: #c8102e !important; color: #ffffff !important; }
  .button--primary:hover, .Button--primary:hover { background-color: #e01b3c !important; }

  /* ---- Tabs ---- */
  .tabs__list, .Tabs, .mod-tabs, .ui-tabs-nav, .ContentList__Tabs {
    background-color: transparent !important; border-color: #2d333b !important; }
  .tabs__list__item, .Tabs__Link, .ui-tabs-nav li a { color: #c4cdd6 !important; }
  .tabs__list__item--active, .Tabs__Link--active, .ui-tabs-selected a {
    color: #e6edf3 !important; border-bottom-color: #c8102e !important; }

  /* ---- Promos / callouts / banners ---- */
  .promo, .scorePromo, .premiumEngagement, .callout, .alert, .notification-bar,
  .takeover, .promoModule, .EdpHeader, .ClubhouseHeader, .ClubhouseHeader.bg-clr-white {
    background-color: #1a1f26 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }

  /* ---- Footer ---- */
  .PageFooter, .PageFooter__Footer, .PageFooter__QuickLinks, #global-footer,
  footer, .footer, .Footer { background-color: #0d1117 !important; border-color: #2d333b !important; }
  .PageFooter a, .PageFooter__QuickLinks a, .Footer a { color: #8ab4d8 !important; }
  .PageFooter__Footer span, .PageFooter small, .copyright { color: #8b949e !important; }

  /* ---- Ad surrounds: dark, no bright leaks (don't theme iframe content) ---- */
  .Ad, .ad, [class*="ad-"], [id*="ad-"], .advertisement, .Ad--banner,
  .Ad--inContent, .ad-banner-wrapper, .sponsoredHeadlines {
    background-color: #14181d !important; border-color: #262c33 !important; }
  .tbl-feed-header-text, .sponsoredHeadlines__title, .ad-feedback-text { color: #8b949e !important; }

  /* ---- Footer legal / OneTrust settings strip (default near-white) ---- */
  .PageFooter__Legal, .PageFooter__Legal__Copyright, .ot-sdk-show-settings,
  #onetrust-consent-sdk .ot-sdk-row, .legal { color: #8b949e !important; }

  /* ---- Catch-all: any element ESPN paints white/near-white inline ---- */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
  /* Dark text ESPN hardcodes (#1d1e1f / #48494a) → light, on our dark surfaces */
  [style*="color: rgb(29, 30, 31)"], [style*="color:#1d1e1f"],
  [style*="color: rgb(72, 73, 74)"], [style*="color:#48494a"] { color: #c4cdd6 !important; }

  /* ---- ESPN hardcoded GREY SCALE (clr-gray-01..09) — applied via CLASSES,
       not inline; drives stat numbers, leader values, box-score metadata,
       glossary, copyright. Remap the WHOLE scale: dark end → light for text. ---- */
  .clr-gray-01, .clr-gray-02 { color: #e6edf3 !important; } /* #151617 / darkest → primary text (numbers, names) */
  .clr-gray-03 { color: #c4cdd6 !important; }               /* #48494a → body */
  .clr-gray-04, .clr-gray-05 { color: #9aa4ae !important; } /* #6c6d6f → muted metadata (still ≥4.5 on cards) */
  /* Module / section / panel titles ESPN colors with a dark grey (#2b2c2d) */
  .Stats__LeadersTitle, .Table__Title, .Card__Header__Title, .module-header,
  .headerCell__title, .pageHeader__title, .Wrapper__Header, .ContentList__Title,
  .Stats__Title, .StatBlock__Title, .TeamLeaders__Title, .clr-black, [class*="__Title"] {
    color: #e6edf3 !important; }
  /* Stat / leader / box-score containers that hardcode the same darks via class */
  .Athlete__Text--2xl-emph, .Athlete__Text--xl-emph, .Athlete__Text--lg-emph,
  .Athlete__PlayerName, .Athlete__Link, .Athlete h3, .Athlete h2,
  .StatBlock__Value, .StatBlockInner__Value, .Leaders__Item__Value,
  .TeamLeaders__Item, .player-leader-value, .fw-bold {
    color: #e6edf3 !important; }
  .Athlete__Text--md-emph, .Athlete__Stats, .Athlete__NameDetails,
  .StatBlock__Label, .Leaders__Item__Label, .glossary__title, .glossary__abbr {
    color: #c4cdd6 !important; }
  .Stats__footerText, .Stats__footerEmph, .Stats__TotalRow, .glossary__item,
  .LegalFooter__Copyright, .LegalFooter__Link, .ContentMetadata,
  .GameInfo__Meta, .Gamestrip__Time, .ScoreboardScoreCell__Note { color: #9aa4ae !important; }
  /* Stat headers / sortable column links that color via class */
  .StatsTable__headerLink, .stats-cell, .Table__TH .AnchorLink,
  .Table__TH svg { color: #c4cdd6 !important; fill: #c4cdd6 !important; }
  /* Box-score line scores + column headings (1 2 3 4 T) → readable text */
  .ScoreboardScoreCell__Value, .ScoreboardScoreCell__Lines,
  .gameLineScore { color: #c4cdd6 !important; }
  .ScoreboardScoreCell__Heading { color: #9aa4ae !important; }
  /* Video duration pill: dark translucent over media, light text */
  .Media__Duration, .Media__Time {
    background-color: rgba(13,17,23,0.78) !important; color: #ffffff !important; }
  /* Scoreboard / game metadata hardcoding the same darks WITHOUT clr-gray-* */
  .ScoreboardScoreCell__Record, .LocationDetail__Item,
  .News__Item__Description, .News__Item__Timestamp,
  .GameInfo, .MatchInfo__Detail, .MatchInfo__Meta { color: #9aa4ae !important; }
  /* Game-info / match-info panels ESPN paints a light grey (#edeef0) */
  .MatchInfo, .GameInfo__Content, .Gamestrip, .competitors {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .MatchInfo__Link, .MatchInfo a { color: #5fb0e6 !important; }

  /* ---- "More Sports" mega-menu (white) — .submenu-wrapper / ul.split ---- */
  .submenu-wrapper, ul.split, ul.split.three, .split.three, .submenu, .sub-nav-menu,
  .Nav__Secondary__Submenu, .Nav__Submenu, .nav-submenu, .navbar-submenu {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .submenu-wrapper a, ul.split a, .submenu a, .Nav__Secondary__Submenu a { color: #e6edf3 !important; }
  .submenu-wrapper a:hover, ul.split a:hover, .submenu a:hover { color: #9bd4ff !important; }

  /* ---- Video-playlist modules ("Top Videos" / "NBA Videos") — white tiles ---- */
  .mediaList, .mediaList__content, .mediaList__link, .video-playlist,
  .video-playlist-item, li.video-playlist-item, .MediaList, .MediaList--highlights,
  .MediaList__list, .MediaList__item, .MediaList__item__wrap, .MediaList__content,
  .VideoList, .VideoPlaylist, .playlist, .playlist__item, .videoPlaylist__item {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .mediaList__link:hover, .MediaList__item:hover, .video-playlist-item:hover,
  .playlist__item:hover { background-color: #21262d !important; }
  .mediaList__title, .MediaList__title, .MediaList__item__description,
  .video-playlist-item__title, .playlist__item__title, .mediaList__link h3,
  .MediaList__item h3 { color: #e6edf3 !important; }
  .mediaList__duration, .MediaList__duration, .MediaList__item__time,
  .MediaList__item__meta, .video-playlist-item__duration,
  .playlist__item__duration, .video-duration { color: #9aa4ae !important; }

  /* ---- Scores carousel: light band past the last chip (#f1f2f3) ---- */
  .scores-carousel, .scores-carousel .wrap, .scoreboard-content .wrap,
  .scores-carousel__inner, .scoreLabel_content, .scoreboard-wrapper, .web-scoreboard,
  .HeaderScoreboard, .HeaderScoreboard--empty, #global-scoreboard .wrap,
  .HeaderScoreboard__Wrapper .wrap {
    background-color: #14181d !important; }

  /* ---- Misc surfaces that default to white ---- */
  .bg-clr-white, .bg-white, [class*="bg-clr-white"] { background-color: #1c2128 !important; }
  hr { border-color: #2d333b !important; }
  ::selection { background-color: #2f6fb8 !important; color: #ffffff !important; }
}
